package com.idfc.ai.runbook.orchestration;
import com.idfc.ai.runbook.api.dto.CreateJobRequest; import java.time.Instant; import java.util.*;
public class RunbookJob { public final UUID id=UUID.randomUUID(); public final String serviceId, requestedCommit, environment, imageTag, repo; public final CreateJobRequest.ExtractionInput extractionInput; public volatile String analyzedCommit, failureCode, failureMessage; public volatile RunbookJobState state=RunbookJobState.RECEIVED; public volatile boolean operationalChange; public final List<String> changedSections=new ArrayList<>(); public final Map<String,String> artifacts=new TreeMap<>(); public final Instant receivedAt=Instant.now(); public volatile Instant updatedAt=receivedAt;
 public RunbookJob(CreateJobRequest r){serviceId=r.serviceId(); requestedCommit=r.repository().commitSha(); environment=r.deployment().environment(); imageTag=r.deployment().imageTag(); repo=r.repository().localPath(); extractionInput=r.extractionInput();} public synchronized void transition(RunbookJobState next){ if(state==RunbookJobState.FAILED||state==RunbookJobState.PUBLISHED) throw new IllegalStateException("terminal job state"); state=next; updatedAt=Instant.now();} public synchronized void fail(String c,String m){state=RunbookJobState.FAILED;failureCode=c;failureMessage=m;updatedAt=Instant.now();} }
